-- This is a hand-derived baseline migration: it captures the verified-
-- green schema produced by the prior multi-file migration set, in a
-- single replayable file. `mlcl create <app>` will scaffold this as
-- migration 0010 and the runtime migration runner will apply it as a
-- single transaction at first boot.
CREATE TABLE public.api_endpoints (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    spec_id uuid NOT NULL,
    user_id uuid NOT NULL,
    method text NOT NULL,
    path text NOT NULL,
    tag text,
    summary text,
    description text,
    parameters jsonb DEFAULT '[]'::jsonb NOT NULL,
    responses jsonb DEFAULT '{}'::jsonb NOT NULL,
    samples jsonb DEFAULT '{}'::jsonb NOT NULL,
    deprecated boolean DEFAULT false NOT NULL,
    resource text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


